css:
.wq-shell{font:14px/1.45 system-ui,sans-serif;color:#172033;background:white;border:1px solid #dfe3ea;border-radius:16px;padding:20px}.wq-head{display:flex;justify-content:space-between;gap:12px;align-items:center}.wq-head h2{margin:2px 0}.wq-kicker{margin:0;color:#64748b;text-transform:uppercase;letter-spacing:.08em;font-size:11px}.wq-count{background:#eef2ff;color:#3730a3;padding:7px 10px;border-radius:999px;font-size:12px}
.wq-controls{display:grid;grid-template-columns:2fr 1fr 1fr 1fr auto;gap:10px;align-items:end;margin:18px 0}.wq-controls label{display:grid;gap:5px;font-size:12px;font-weight:700;color:#475569}.wq-controls input,.wq-controls select{width:100%;box-sizing:border-box;border:1px solid #cbd5e1;border-radius:8px;padding:9px;background:white;color:#0f172a}.wq-clear{border:1px solid #cbd5e1;background:#f8fafc;border-radius:8px;padding:9px 12px;cursor:pointer}
.wq-table-wrap{overflow:auto}.wq-shell table{width:100%;border-collapse:collapse}.wq-shell th,.wq-shell td{text-align:left;padding:10px 8px;border-bottom:1px solid #e5e7eb}.wq-shell th{font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:#64748b}.wq-pill{display:inline-block;padding:3px 8px;border-radius:999px;background:#f1f5f9;font-size:12px}.wq-empty{padding:22px;text-align:center;color:#64748b}
@media(max-width:820px){.wq-controls{grid-template-columns:1fr 1fr}.wq-search{min-width:0}}

js:
const q=root.querySelector('.wq-search'),status=root.querySelector('.wq-status'),owner=root.querySelector('.wq-owner'),sort=root.querySelector('.wq-sort'),tbody=root.querySelector('tbody'),count=root.querySelector('.wq-count'),empty=root.querySelector('.wq-empty');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[c]));
function syncOptions(tasks){
  const statuses=[...new Set(tasks.map(t=>t.status).filter(Boolean))].sort();
  const owners=[...new Set(tasks.map(t=>t.owner).filter(Boolean))].sort();
  const sv=status.value,ov=owner.value;
  status.innerHTML='<option value="">All statuses</option>'+statuses.map(v=>`<option>${esc(v)}</option>`).join('');
  owner.innerHTML='<option value="">All owners</option>'+owners.map(v=>`<option>${esc(v)}</option>`).join('');
  if(statuses.includes(sv))status.value=sv;if(owners.includes(ov))owner.value=ov;
}
function render(rebuild=true){
  const tasks=[...(api.getState('tasks')||[])]; if(rebuild)syncOptions(tasks);
  const needle=q.value.trim().toLowerCase(),sv=status.value,ov=owner.value;
  let rows=tasks.filter(t=>{
    const hay=`${t.title||''} ${t.owner||''}`.toLowerCase();
    return (!needle||hay.includes(needle))&&(!sv||t.status===sv)&&(!ov||t.owner===ov);
  });
  rows.sort((a,b)=>sort.value==='due'
    ? String(a.due||'9999-99-99').localeCompare(String(b.due||'9999-99-99'))||String(a.title||'').localeCompare(String(b.title||''))
    : String(a.title||'').localeCompare(String(b.title||'')));
  tbody.innerHTML=rows.map(t=>`<tr><td><strong>${esc(t.title)}</strong></td><td>${esc(t.owner||'—')}</td><td><span class="wq-pill">${esc(t.status||'—')}</span></td><td>${esc(t.due||'—')}</td></tr>`).join('');
  count.textContent=`${rows.length} of ${tasks.length} tasks`;
  empty.hidden=rows.length!==0;
}
[q,status,owner,sort].forEach(el=>el.addEventListener(el===q?'input':'change',()=>render(false)));
root.querySelector('.wq-clear').addEventListener('click',()=>{q.value='';status.value='';owner.value='';sort.value='title';render(false);});
const unsubscribe=api.subscribe(()=>render(true));
render(true);
